// Emit the cold-start seed as idempotent SQL (db/seeds/seed_ontology.sql)
// so applications load it through their own migrate pipelines with no
// dependency on this package at load time. Regenerated at build.
import { mkdirSync, writeFileSync } from 'node:fs'
import { SEED_CONCEPTS, normalizeTopicLabel } from '../dist/index.js'

const quote = (value) => value === null || value === undefined
  ? 'null'
  : `'${String(value).replace(/'/g, "''")}'`

const lines = [
  '-- GENERATED by scripts/emit-seed-sql.mjs from the canonical seed. Do not',
  '-- edit by hand. Idempotent: existing rows (including application edits)',
  '-- are left alone.',
  '',
]

const SEED_VERSION = 1

for (const concept of SEED_CONCEPTS) {
  lines.push(
    `insert into onto_concept (slug, name, level, summary, emoji, seed_version)`
    + ` values (${quote(concept.slug)}, ${quote(concept.name)}, ${quote(concept.level)},`
    + ` ${quote(concept.summary)}, ${quote(concept.emoji ?? null)}, ${SEED_VERSION})`
    + ` on conflict (slug) do nothing;`,
  )
}
lines.push('')
for (const concept of SEED_CONCEPTS) {
  (concept.parents ?? []).forEach((parent, ordinal) => {
    lines.push(
      `insert into onto_edge (parent_id, child_id, ordinal)`
      + ` select p.id, c.id, ${ordinal} from onto_concept p, onto_concept c`
      + ` where p.slug = ${quote(parent)} and c.slug = ${quote(concept.slug)}`
      + ` on conflict do nothing;`,
    )
  })
}
lines.push('')
for (const concept of SEED_CONCEPTS) {
  const labels = [...new Set([concept.name, concept.slug, ...(concept.aliases ?? [])])]
  for (const label of labels) {
    const normalized = normalizeTopicLabel(label)
    if (!normalized) continue
    lines.push(
      `insert into onto_alias (concept_id, label, normalized_label, status, source)`
      + ` select id, ${quote(label)}, ${quote(normalized)}, 'approved', 'seed'`
      + ` from onto_concept where slug = ${quote(concept.slug)}`
      + ` on conflict (normalized_label) do nothing;`,
    )
  }
}
lines.push('')

mkdirSync('db/seeds', { recursive: true })
writeFileSync('db/seeds/seed_ontology.sql', lines.join('\n'))
console.log(`seed_ontology.sql written (${SEED_CONCEPTS.length} concepts)`)
